function showAuth(v){el('[data-testid="auth-form"]').style.display=v?'block':'none'}
function authError(t){var x=el('[data-testid="auth-error"]);x.textContent=t||'';x.style.display=t?'block':'none'}
function renderWorkspace(w,channels){state.workspace=w;el('[data-testid="workspace-header"]').textContent=w.name;var list=el('[data-testid="channel-list"]);list.innerHTML='';channels.forEach(function(c){var b=document.createElement('button');b.className='row';b.dataset.testid='channel-entry';b.dataset.channelId=c.id;b.dataset.channelName=c.name;b.textContent='#'+c.name;b.onclick=function(){selectChannel(c)};list.appendChild(b)});if(channels[0])selectChannel(channels[0])}
