async function selectChannel(c){state.channel=c;el('[data-testid="channel-title"]').textContent='#'+c.name;el('[data-testid="channel-topic"]').textContent=c.topic||'';var x=await api('GET','/channels/'+c.id+'/messages');var box=el('[data-testid="message-list"]);box.innerHTML='';(x.data.messages||[]).forEach(function(m){var row=document.createElement('div');row.dataset.testid='message';row.innerHTML='<span data-testid="message-body">'+m.body+'</span>';box.appendChild(row)});el('[data-testid="channel-empty-state"]').style.display=(x.data.messages||[]).length?'none':'block'}
async function submitAuth(){var f=el('[data-testid="auth-form"]),u=f.querySelector('[name="username"]').value,p=f.querySelector('[name="password"]').value;var x=await api('POST',state.signup?'/auth/register':'/auth/login',{username:u,password:p,display_name:u});if(x.status>=400){authError(x.data.error||'Unable to authenticate');return}state.token=x.data.token;state.user=x.data.user;localStorage.setItem('huddle.token',state.token);el('[data-testid="current-user"]').textContent=state.user.display_name;showAuth(false);authError('');loadWorkspaces()}
async function createWorkspace(){var f=el('[data-testid="workspace-create-form"]),slug=f.querySelector('[name="workspace-slug"]').value||'workspace',name=f.querySelector('[name="workspace-name"]').value||slug;var x=await api('POST','/workspaces',{slug:slug,name:name});if(x.status<300){var w=await api('GET','/workspaces/'+slug);renderWorkspace(w.data.workspace,w.data.channels||[])}}
async function createChannel(){var f=el('[data-testid="create-channel-form"]),name=f.querySelector('[name="channel-name"]').value;var x=await api('POST','/workspaces/'+state.workspace.slug+'/channels',{name:name,is_private:el('[data-testid="create-channel-private"]').checked});if(x.status>=400){el('[data-testid="create-channel-error"]').textContent=x.data.error||'Unable to create channel';return}el('[data-testid="create-channel-modal"]').style.display='none';var w=await api('GET','/workspaces/'+state.workspace.slug);renderWorkspace(w.data.workspace,w.data.channels||[])}
async function sendMessage(){if(!state.channel)return;var f=el('[data-testid="message-input"]),body=f.value;if(!body.trim())return;await api('POST','/channels/'+state.channel.id+'/messages',{body:body});f.value='';selectChannel(state.channel)}
