p='/app/static/app.js';s=open(p).read()
a=s.index('async function selectChannel(');b=s.index('async function submitAuth(',a)
new=r'''function renderMessages(messages){
 var box=el('[data-testid="message-list"]');box.innerHTML='';
 messages.forEach(function(m){
  var row=document.createElement('div');row.dataset.testid='message';row.dataset.messageId=m.id;row.className='row';
  var av=document.createElement('span');av.dataset.testid='message-avatar';av.textContent='● ';
  var au=document.createElement('span');au.dataset.testid='message-author';au.textContent=(m.author&&m.author.username)||((state.user&&state.user.username)||'user');
  var tm=document.createElement('span');tm.dataset.testid='message-time';tm.textContent=' '+new Date(m.created_at).toLocaleString()+' ';
  var body=document.createElement('span');body.dataset.testid='message-body';body.textContent=m.body;
  row.append(av,au,tm,body);
  if(m.edited_at){var ed=document.createElement('span');ed.dataset.testid='message-edited';ed.textContent=' (edited)';row.append(ed)}
  var rc=document.createElement('span');rc.dataset.testid='reply-count';rc.textContent=m.reply_count===1?' 1 reply':(m.reply_count||0)+' replies';row.append(rc);
  var bar=document.createElement('span');bar.className='toolbar';
  var edit=document.createElement('button');edit.dataset.testid='edit-message-btn';edit.textContent='Edit';edit.onclick=function(){var inp=document.createElement('input');inp.dataset.testid='edit-message-input';inp.value=m.body;body.replaceWith(inp);inp.focus();inp.onkeydown=async function(e){if(e.key==='Enter'){var x=await api('PATCH','/messages/'+m.id,{body:inp.value});if(x.status<300)selectChannel(state.channel)}}};bar.append(edit);
  var thr=document.createElement('button');thr.dataset.testid='open-thread-btn';thr.textContent='Thread';thr.onclick=function(){openThread(m,row)};bar.append(thr);
  var react=document.createElement('button');react.dataset.testid='reaction-button';react.textContent='React';react.onclick=function(){showPicker(m,row)};bar.append(react);
  var del=document.createElement('button');del.dataset.testid='delete-message-btn';del.textContent='Delete';del.onclick=async function(){var x=await api('DELETE','/messages/'+m.id);if(x.status<300)selectChannel(state.channel)};bar.append(del);row.append(bar);
  (m.reactions||[]).forEach(function(r){var chip=document.createElement('span');chip.dataset.testid='reaction-chip';chip.textContent=r.emoji+' '+r.count;row.append(chip)});
  box.appendChild(row);
 });
 el('[data-testid="channel-empty-state"]').style.display=messages.length?'none':'block'
}
function showPicker(m,row){var old=row.querySelector('[data-testid="emoji-picker"]');if(old)old.remove();var p=document.createElement('span');p.dataset.testid='emoji-picker';['😀','👍','🎉','❤️','🚀','👀'].forEach(function(e){var o=document.createElement('button');o.dataset.testid='emoji-option';o.textContent=e;o.onclick=async function(){await api('POST','/messages/'+m.id+'/reactions',{emoji:e});selectChannel(state.channel)};p.appendChild(o)});row.appendChild(p)}
async function openThread(m,row){var panel=el('[data-testid="thread-panel"]');panel.style.display='block';panel.innerHTML='<div>Thread</div><div data-testid="thread-messages"></div><textarea data-testid="thread-input"></textarea><button data-testid="thread-send" data-button-role="primary">Reply</button><button data-testid="close-thread" data-button-role="secondary">Close</button>';var load=async function(){var x=await api('GET','/messages/'+m.id+'/replies');var q=panel.querySelector('[data-testid="thread-messages"]');q.innerHTML='';(x.data.replies||[]).forEach(function(z){var d=document.createElement('div');d.textContent=z.body;q.appendChild(d)})};await load();panel.querySelector('[data-testid="thread-send"]').onclick=async function(){var i=panel.querySelector('[data-testid="thread-input"]');if(i.value.trim()){await api('POST','/channels/'+m.channel_id+'/messages',{body:i.value,parent_id:m.id});i.value='';await load();selectChannel(state.channel)}};panel.querySelector('[data-testid="close-thread"]').onclick=function(){panel.style.display='none'};load()}
async function selectChannel(c){if(state.workspace){var fresh=await api('GET','/workspaces/'+state.workspace.slug);var found=(fresh.data.channels||[]).find(function(x){return String(x.id)===String(c.id)});if(found)c=found}state.channel=c;el('[data-testid="channel-title"]').textContent='#'+c.name;el('[data-testid="channel-topic"]').textContent=c.topic||'';var x=await api('GET','/channels/'+c.id+'/messages');renderMessages(x.data.messages||[])}
'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
